}

.index-hero h1 {
  color: white;
  font-size: clamp(2rem, 5vw, 3.5rem);
}

.index-hero-subtitle {
  font-size: 1.25rem;
  color: var(--color-accent-on-dark);
  margin-bottom: var(--spacing-lg);
}

.index-hero-image {
  width: 100%;
  height: auto;
  border-radius: var(--radius);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
}

.index-overview {
  padding: var(--spacing-2xl) 0;
  background-color: var(--color-bg);
}

.index-overview h2 {
  text-align: center;
  margin-bottom: var(--spacing-2xl);
}

.index-feature-card {
  text-align: center;
}

.index-feature-card h3 {
  margin-bottom: var(--spacing-md);
}

.index-curriculum-section {
  padding: var(--spacing-2xl) 0;
  background-color: var(--color-bg-alt);
}

.index-curriculum-intro {
  text-align: center;
  font-size: 1.1rem;
  margin-bottom: var(--spacing-2xl);
}

.index-curriculum-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: var(--spacing-lg);
  margin-bottom: var(--spacing-2xl);
}

.index-curriculum-module {
  background-color: white;
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: var(--spacing-lg);
  transition: var(--transition);
}

.index-curriculum-module:hover {
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.1);
  transform: translateY(-4px);
}

.index-module-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: var(--spacing-md);
  margin-bottom: var(--spacing-md);
}

.index-module-header h3 {
  margin-bottom: 0;
  flex: 1;
}

.index-module-duration {
  display: inline-block;
  background-color: var(--color-accent);
  color: var(--color-text);
  padding: var(--spacing-sm) var(--spacing-md);
  border-radius: var(--radius);
  font-size: 0.875rem;
  font-weight: 600;
  white-space: nowrap;
  flex-shrink: 0;
}

.index-curriculum-module p {
  margin-bottom: var(--spacing-md);
}

.index-module-lessons {
  list-style: none;
  padding: 0;
  margin: 0;
}

.index-module-lessons li {
  padding-left: var(--spacing-lg);
  position: relative;
  margin-bottom: var(--spacing-sm);
  color: var(--color-text-light);
}

.index-module-lessons li::before {
  content: "✓";
  position: absolute;
  left: 0;
  color: var(--color-success);
  font-weight: 700;
}

.index-curriculum-stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--spacing-lg);
  padding: var(--spacing-2xl);
  background-color: white;
  border-radius: var(--radius);
  text-align: center;
  border: 2px solid var(--color-border);
}

.index-stat strong {
  display: block;
  font-size: 1.75rem;
  color: var(--color-primary);
  margin-bottom: var(--spacing-sm);
}

.index-stat span {
  display: block;
  font-size: 0.9rem;
  color: var(--color-text-light);
}

.index-testimonials-section {
  padding: var(--spacing-2xl) 0;
  background-color: white;
}

.index-testimonials-intro {
  text-align: center;
  font-size: 1.1rem;
  margin-bottom: var(--spacing-2xl);
}

.index-testimonials-section h2 {
  text-align: center;
  margin-bottom: var(--spacing-lg);
}

.index-testimonial-card {
  display: flex;
  flex-direction: column;
}

.index-testimonial-header {
  margin-bottom: var(--spacing-md);
}

.index-testimonial-stars {
  color: var(--color-accent);
  font-size: 1.1rem;
  margin-bottom: var(--spacing-sm);
}

.index-testimonial-author {
  margin-bottom: var(--spacing-sm);
  font-weight: 700;
  color: var(--color-primary);
}

.index-testimonial-role {
  font-size: 0.9rem;
  color: var(--color-text-light);
  margin-bottom: 0;
}

.index-testimonial-text {
  flex: 1;
  font-style: italic;
  line-height: 1.7;
}

.index-enroll-section {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-light) 100%);
  color: white;
  padding: var(--spacing-2xl) 0;
}

.index-enroll-content {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: var(--spacing-lg);
  max-width: 700px;
  margin: 0 auto;
}

.index-enroll-section h2 {
  color: white;
}

.index-enroll-section p {
  color: var(--color-accent-on-dark);
}

.index-pricing-box {
  background-color: rgba(255, 255, 255, 0.1);
  border: 2px solid var(--color-accent-on-dark);
  border-radius: var(--radius);
  padding: var(--spacing-lg);
  margin: var(--spacing-lg) 0;
  width: 100%;
}

.index-price-main {
  margin-bottom: var(--spacing-md);
}

.index-price-amount {
  display: block;
  font-size: 2.5rem;
  font-weight: 700;
  color: var(--color-accent-on-dark);
}

.index-price-label {
  display: block;
  font-size: 1rem;
  color: var(--color-accent-on-dark);
}

.index-price-desc {
  margin-top: var(--spacing-md);
  font-size: 0.95rem;
}

.index-price-alt {
  padding-top: var(--spacing-md);
  border-top: 1px solid var(--color-accent-on-dark);
}

.index-price-alt p {
  margin-bottom: var(--spacing-sm);
}

.index-enroll-features {
  text-align: left;
  background-color: rgba(255, 255, 255, 0.05);
  padding: var(--spacing-lg);
  border-radius: var(--radius);
  width: 100%;
}

.index-enroll-features p {
  margin-bottom: var(--spacing-sm);
  text-align: left;
}

.index-enroll-btn {
  padding: var(--spacing-lg) var(--spacing-2xl);
  font-size: 1.1rem;
  margin-top: var(--spacing-lg);
}

.index-enroll-support {
  font-size: 0.95rem;
}

.index-enroll-support a {
  color: var(--color-accent-on-dark);
}

@media (max-width: 600px) {
  .index-hero .container {
    grid-template-columns: 1fr;
  }

  .index-hero {
    min-height: auto;
    padding: var(--spacing-xl) 0;
  }

  .index-hero h1 {
    font-size: 2rem;
  }

  .index-hero-subtitle {
    font-size: 1rem;
  }

  .index-curriculum-list {
    grid-template-columns: 1fr;
  }

  .index-curriculum-stats {
    grid-template-columns: 1fr 1fr;
  }

  .index-module-header {
    flex-direction: column;
  }

  .index-module-duration {
    width: 100%;
    text-align: center;
  }

  .index-pricing-box {
    margin: var(--spacing-md) 0;
  }

  .index-price-amount {
    font-size: 2rem;
  }

  .index-enroll-btn {
    width: 100%;
  }
}

@media (min-width: 601px) {
  .index-hero {
    padding: var(--spacing-2xl) 0;
  }

  .index-curriculum-stats {
    grid-template-columns: repeat(4, 1fr);
  }
}
